'use strict';

// MODULES //

var path = require( 'node:path' );
var readFile = require( 'node:fs/promises' ).readFile;
var assertSchema = require( '@data-apis/schema/assert' );
var serializeIndex = require( '@data-apis/record/serialize-index' );


// MAIN //

/**
* Reads and validates the deterministic data index.
*
* @param {string} dataDirectory - data directory
* @returns {Promise<Object>} index
*/
async function loadIndex( dataDirectory ) {
	var filePath = path.join( dataDirectory, 'index.json' );
	var raw;
	var index;

	try {
		raw = await readFile( filePath, 'utf8' );
	} catch ( error ) {
		throw new Error( 'Unable to read data index ' + filePath + ': ' + error.message, {
			'cause': error
		} );
	}
	index = JSON.parse( raw );
	assertSchema( 'data-index-v1', index );
	if ( raw !== serializeIndex( index.records ) ) {
		throw new Error( 'data/index.json is not deterministically sorted and serialized' );
	}
	return index;
}


// EXPORTS //

module.exports = loadIndex;
